import { useState } from 'react'

export default function App() {
  const [count, setCount] = useState(0)

  return (
    <div style={{ fontFamily: 'system-ui, sans-serif', padding: '2rem', textAlign: 'center', backgroundColor: '#0f172a', color: '#f8fafc', minHeight: '100vh' }}>
      <h1>⚡ VibeCode React Starter</h1>
      <p>Welcome to your interactive in-browser coding playground!</p>
      <div style={{ marginTop: '2rem' }}>
        <button 
          onClick={() => setCount((c) => c + 1)}
          style={{ padding: '0.75rem 1.5rem', fontSize: '1rem', borderRadius: '0.5rem', border: 'none', backgroundColor: '#3b82f6', color: 'white', cursor: 'pointer' }}
        >
          Count is {count}
        </button>
      </div>
    </div>
  )
}

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
})

export default function Home() {
  return (
    <main style={{ padding: '2rem', fontFamily: 'sans-serif', textAlign: 'center' }}>
      <h1>⚡ VibeCode Next.js Starter</h1>
      <p>Building fullstack apps in the browser!</p>
    </main>
  );
}

const express = require('express');
const app = express();
const port = 3000;

app.get('/', (req, res) => {
  res.send('<h1>⚡ VibeCode Express Starter</h1><p>Server running successfully in WebContainer!</p>');
});

app.listen(port, () => {
  console.log(`Server running on port ${port}`);
});

import { serve } from '@hono/node-server'
import { Hono } from 'hono'

const app = new Hono()

app.get('/', (c) => {
  return c.text('Hello Hono from VibeCode WebContainer!')
})

serve({ fetch: app.fetch, port: 3000 }, (info) => {
  console.log(`Server is running on http://localhost:${info.port}`)
})
